typedef struct { int (*acquire)(void *); int (*release)(void *); void *self; } lock_strategy;

const char *file_cache_find(file_cache *fc, const char *path)
{
    const char *result;
    if (fc->lock.acquire(fc->lock.self) != 0)
        return NULL;
    result = find_i(fc, path);          /* _i assumes the lock is held */
    fc->lock.release(fc->lock.self);    /* single exit: releases on the only return */
    return result;
}
/* policy family: pthread_mutex_t (NORMAL/ERRORCHECK/RECURSIVE), pthread_rwlock_t, no-op */
